    var show_manufacturer = it.data_instance_properties.show_manufacturer;
    var show_points = it.data_instance_properties.show_points;
    var show_add_to_favorites = it.data_instance_properties.show_add_to_favorites;
    var show_small_img_color = it.data_instance_properties.show_small_img_color;

	var product = it.product;
    var prices = it.prices;
    var media = it.medias[0];
    var medias_thumb = !_.isUndefined(it.instance_properties) ? it.instance_properties.thumb : it.data_widget_params.thumb;
    var issoldout = it.is_sold_out;
    var product_id = product.product_id;

    var link_prod = PageManager.url(it.seo_data.segment);

	if(_.isUndefined(static_url)){
        var static_url = PageManager.staticUrl;
    }

}}

{{
    var count = 0;
    if (typeof it.attributes._selectionsAttributes != "undefined" || it.attributes._selectionsAttributes != null){ 
        for (var key in it.attributes._selectionsAttributes[1].values) { 
            count = count + 1; 
        } 
    } 
}}

{{
    var CDU_ljVisUnidade = 0;
    var extra1 = it.product.extra1;
    if( (!_.isEmpty(extra1)) ){
        extra1 = JSON.parse(extra1);
        CDU_ljVisUnidade = (_.has(extra1, 'CDU_ljVisUnidade')) ? parseInt(extra1.CDU_ljVisUnidade) : 0;
    }

	var CDU_PrecoSobConsulta = 0;
    var extra2 = it.product.extra2;
    if( (!_.isEmpty(extra2)) ){
        extra2 = JSON.parse(extra2);
        CDU_PrecoSobConsulta = (_.has(extra2, 'CDU_PrecoSobConsulta')) ? parseInt(extra2.CDU_PrecoSobConsulta) : 0;
    }
	
	var is_logged_in = it.instance_properties && !_.isUndefined(it.instance_properties.entity.is_logged_in) ? it.instance_properties.entity.is_logged_in : $('.site').hasClass('user-logged');

	var user_group_b2c = $('.site').hasClass('user_B2C');



}}


{{? _.isObject(it.product) }}
    <div class="product-list-content js-product-box col-xs-12">
         <div class="col-xs-12 tag-prod-zone p-x-0">

            

            {{? product.is_highlight === "1" }}
                <div class="tag-prod tag-highlighted">{{# Beevo._('LANG_SHOP_IS_HIGHLIGHT') }}</div>
            {{?}}

            {{? product.is_new === "1"  }}
                <div class="tag-prod tag-new">{{# Beevo._('LANG_SHOP_PRODUCT_NOVELTY') }}</div>
            {{?}}

            {{? issoldout && 0 }}
                <div class="tag-prod tag-soldout">{{# Beevo._('LANG_SHOP_PRODUCTDETAILS_SOLD_OUT') }}</div>
            {{?}}

            {{? !_.isEmpty(it.tags) }}
                {{ _.each(it.tags, function(tag, index) { }}
                {{
                    var time_validate = true;
                    var time_now = Date.now();
                    if(tag.start_date != null && tag.end_date != null){
                        time_validate = (Date.parse(tag.start_date) <= time_now && Date.parse(tag.end_date) >= time_now);
                    }
                }}
                    {{? time_validate  }}
                        {{? tag.visible == "1" }}
                            <div class="tag-prod {{= tag.class }}">{{= tag.tag_name }}</div>
               
                        {{?}}
                    {{?}}
                {{ }); }}
            {{?}}

        </div>
        <div class="product-slider col-xs-12 p-x-0">
            <div class="js-shopping-container shopping-container">
                <!-- IMAGES -->
                <div id="ProductListGallery_{{= product_id }}" class="carousel slide" data-ride="false" data-interval="false"> 
                    {{ var current_product_name = product.name; }}
                    <div class="carousel-inner" role="listbox">
                        <div class="item active {{? issoldout }}soldout-img{{?}}">
                            <a href="{{= link_prod }}">
                                
                                {{ if ( ! current_product_name ) { console.log("PLEASE FIX PRODUCT NAME, must be defined"); } }}
                                
                                {{= BeevoElement.image({
                                	"placeholder": static_url + '/layouts/Gama/images/no-image-product.png',

                                    "src":!_.isUndefined(media[medias_thumb]) ? media[medias_thumb] : static_url + '/layouts/Gama/images/no-image-product.png',

                                    "class": "img-responsive",
                                    "alt": current_product_name,
                                    "title": current_product_name,
                                    "height":  "308",
                                    "width": "308",
                                
                                    "style": "min-height:308px;max-height:340px;"
                                }) }}
                                
                            </a>
                        </div>
                    </div>

                    {{? show_add_to_favorites }}
                        {{? it.is_favorite }}
                        <button class="fav js-favorite js_remove_favorite favorite-added" data-parent-id="{{= it.product.product_id }}">
                            <i class="fa fa-bookmark before-left"></i>
                        </button>
                        {{??}}
                        <button class="fav js-choose-favorite-list js-favorite" 
                        aria-label="{{= Beevo._('LANG_SHOP_FAVORITOS_HEADER') }}" title="{{= Beevo._('LANG_SHOP_FAVORITOS_HEADER') }}" data-toggle="tooltip" data-placement="top"        
                        data-product-id="{{= it.product.product_id }}"
                        onclick="_.isFunction(window.openSideRightWidget) && window.openSideRightWidget(this)" 
                        data-target-widget="js_Open_add_edit_list_favorite_all" 
                        Open_widget="js_Open_add_edit_list_favorite">
                            <i class="fa fa-bookmark before-left"></i>
                        </button>
                        {{?}}
                    {{?}}
                    {{? show_comparator }}
                    <div class="pull-right compare-block" title="{{= Beevo._('LANG_SHOP_COMPARE_PROD_ALT')}}" data-toggle="tooltip" data-placement="top">
                        {{ var compare_options = {
                            'id' : 'compare-' + product.sku,
                            'class': 'checkbox js-compare clickable m-y-0',
                            'wrap-class': 'flex-container row-left compare p-x-0 m-b-0' + (it.product_in_compare ? 'added' : ''),
                            'label': ''
                            };
                            }}

                        {{ if( it.product_in_compare ) { }}
                            {{ compare_options.checked = 'checked'; }}
                        {{ } }}
                        {{= BeevoElement.input("checkbox", compare_options) }}
                    </div>
                    {{?}}

                    
                    {{? prices.has_discount && !CDU_PrecoSobConsulta && (is_logged_in && (!user_group_b2c)) }}
                        <div class="tag-prod tag-discount">-{{= prices.discount_percentage }}%</div>
                    {{?}}
                </div>
            </div>
        </div>
        <div class="product-details-info col-xs-12"> 
            {{? show_manufacturer && it.manufacturer }}
            <div class="col-xs-12 p-x-0 product-manufacture-block">
                <span class="product-manufacturer font-size-rg font-bold text-color-project text-transform-uppercase line-height-normal">
                     {{? it.manufacturer.segment }}
                        <a class="product-manufacturer font-size-rg font-bold text-color-project text-transform-uppercase line-height-normal" href="/{{= it.manufacturer.segment }}">
                     {{?}}
                        {{= it.manufacturer.name }}
                     {{? it.manufacturer.segment }}
                        </a>
                     {{?}}
                </span>
            </div>
            {{?}} 
            {{? current_product_name }}
            <div class="col-xs-12 p-x-0 product-name-block mt-1 mb-1">
                <a class="invert-link font-size-xmd font-semi-bold line-height-normal" href="{{= link_prod }}">
                    <h3 class="product-name font-size-xmd font-semi-bold line-height-normal link invert-link">{{= current_product_name }}</h3>
                </a>
            </div>
            {{?}}   
           
            <div class="col-xs-12 p-x-0 product-prices-block">
                {{? show_prices }}
                    {{ var has_factor = false; }}
                    {{ var prices_with_conversion_factor = it.prices_with_conversion_factor; }}
                    {{ var visible_sell_unit = it.visible_sell_unit; }}
                    {{ var sell_unit = it.sell_unit; }}

                    {{? prices.conversion_factor != 1 || (visible_sell_unit && !_.isUndefined(visible_sell_unit.sell_unit_id) && _.contains(['16','17','18','19','20','21','22','26','30'], visible_sell_unit.sell_unit_id.toString())) }}
                        {{ has_factor = true; }}
                    {{?}}

                    
                    <div class="col-xs-12 p-x-0 color-text-proj-grey-800 font-semi-bold font-size-sm line-height-normal">
                        {{? count > 1 && CDU_PrecoSobConsulta !== 1}}
                        {{# Beevo._('LANG_SHOP_PRICE_START_AT') }}
                        {{??}}
                        &nbsp;
                        {{?}}
                    </div>
                    
                    {{? CDU_PrecoSobConsulta === 1 }}
                        <div class="col-xs-12 p-x-0 flex-container row-left text-color-3 font-semi-bold font-size-xlmd line-height-normal">
                            {{= Beevo._('LANG_PRICE_CDU_PRECO_SOB_CONSULTA') }}
                        </div>
                    {{??}}
                        {{? CDU_ljVisUnidade === 1 }}
                            {{? has_factor }}
                            <div class="col-xs-12 p-x-0 flex-container row-left text-color-3 font-semi-bold font-size-xlmd line-height-normal">
                                    {{? prices_with_conversion_factor.hide_tax }}
                                        {{= prices_with_conversion_factor.sales_price }}
                                    {{??}}
                                        {{= prices_with_conversion_factor.sales_price_with_tax }}
                                    {{?}}
                                    (
                                        {{= prices_with_conversion_factor.conversion_factor }}
                                        {{? sell_unit }}
                                            {{= sell_unit.description }}
                                        {{?}}
                                    )
                                </div>
                            {{?}}
                            {{? prices.has_previous_price }}
                            <div class="col-xs-12 p-x-0 flex-container row-left">
                                <span class="text-color-3 font-semi-bold font-size-xlmd line-height-normal me-3">
                                    {{? prices.hide_tax }}
                                        {{= prices.sales_price }}
                                    {{??}}
                                        {{= prices.sales_price_with_tax }}
                                    {{?}}

                                    {{? has_factor && visible_sell_unit }}
                                        / {{= visible_sell_unit.description }}
                                    {{??}}
                                        {{? prices.conversion_factor = 1  && visible_sell_unit }}
                                            / {{= visible_sell_unit.description }}
                                        {{?}}
                                    {{?}}
                                    </span>
                                {{? (is_logged_in && (!user_group_b2c)) }}
                                    <span class="font-size-xmd color-text-proj-grey-800 line-height-normal font-semi-bold">
                                        <span class="text-line-through">
                                            {{? prices.hide_tax }}
                                                {{= prices.previous_price }}
                                            {{??}}
                                                {{= prices.previous_price_with_tax }}
                                            {{?}}
                                        </span>
                                        {{? has_factor && visible_sell_unit }}
                                            / {{= visible_sell_unit.description }}
                                        {{??}}
                                            {{? prices.conversion_factor = 1  && visible_sell_unit }}
                                                / {{= visible_sell_unit.description }}
                                            {{?}}
                                        {{?}}
                                        <span class="ms-2">{{= Beevo._('LANG_SHOP_PRODUCT_PVRP') }}</span>
                                    </span>
                                {{?}}
                            </div>
                            {{??}}
                                <div class="col-xs-12 p-x-0 flex-container row-left text-color-3 font-semi-bold font-size-xlmd line-height-normal">
                                    {{? prices.hide_tax }}
                                        {{= prices.sales_price }}
                                    {{??}}
                                        {{= prices.sales_price_with_tax }}
                                    {{?}}

                                    {{? has_factor && visible_sell_unit }}
                                        / {{= visible_sell_unit.description }}
                                    {{?}}
                                </div>
                            {{?}}
                        {{??}}
                            {{? prices.has_previous_price }}
                                <div class="col-xs-12 p-x-0 flex-container row-left">
                                    <span class="text-color-3 font-semi-bold font-size-xlmd line-height-normal me-3">
                                        {{? prices.hide_tax }}{{= prices.sales_price }}{{??}}{{= prices.sales_price_with_tax }}{{?}}
                                        {{? has_factor && visible_sell_unit }}
                                            / {{= visible_sell_unit.description }}
                                        {{?}}
                                    </span>
                                
                                    {{? prices.previous_price_unformatted > prices.sales_price_unformatted }}
                                        {{? prices.has_previous_price }}
                                            {{? (is_logged_in && (!user_group_b2c)) }}
                                                <del class="font-size-xmd color-text-proj-grey-800 line-height-normal font-semi-bold">
                                                    {{? prices.hide_tax }}{{= prices.previous_price }}{{??}}{{= prices.previous_price_with_tax }}{{?}}
                                                    {{? has_factor && visible_sell_unit }}
                                                        / {{= visible_sell_unit.description }}
                                                    {{?}}
                                                </del>
                                            {{?}}
                                        {{??}}
                                            {{? (is_logged_in && (!user_group_b2c)) }}
                                                <span class="font-size-xmd color-text-proj-grey-800 line-height-normal font-semi-bold">
                                                    {{? prices.hide_tax }}{{= prices.sales_price }}{{??}}{{= prices.sales_price_with_tax }}{{?}}
                                                    {{? has_factor && visible_sell_unit }}
                                                        / {{= visible_sell_unit.description }}
                                                    {{?}}
                                                </span>
                                            {{?}}
                                        {{?}}
                                    {{?}}
                                </div>
                            {{??}}
                                <div class="col-xs-12 p-x-0 flex-container row-left text-color-3 font-semi-bold font-size-xlmd line-height-normal">
                                    {{? prices.hide_tax }}
                                        {{= prices.sales_price }}
                                    {{??}}
                                        {{= prices.sales_price_with_tax }}
                                    {{?}}

                                    {{? has_factor && visible_sell_unit }}
                                        / {{= visible_sell_unit.description }}
                                    {{?}}
                                </div>
                            {{?}}
                        {{?}}
                    {{?}}

                    {{? !_.isUndefined(it.extra_fields['unidade_medida_site']) }}
                    {{ un_product_id = _.allKeys(it.extra_fields['unidade_medida_site'])[0]; }}
                        {{? !_.isUndefined(un_product_id) && !_.isEmpty(un_product_id) }}
                            <div class="col-xs-12 p-x-0 font-size-xsm color-text-proj-grey-800 line-height-normal font-semi-bold mt-1">
                            {{ var price_factor_conversao = 0; }}
                            {{ var price_product = 0; }}
                            {{ var factor_conversao = it.extra_fields['unidade_medida_site'][un_product_id]['factor_conversao']; }}
                            {{? (factor_conversao > 0) && (factor_conversao != 9999) }}
                                {{ price_product = prices.sales_price_unformatted; }}
                                {{ cost_price_product = prices.cost_price_unformatted; }}
                                {{ price_factor_conversao = price_product / factor_conversao; }}
                                {{? (price_product == it.extra_fields['unidade_medida_site'][un_product_id]['cost_price']) || (_.keys(it.childrens).length == 1) || (cost_price_product == it.extra_fields['unidade_medida_site'][un_product_id]['cost_price']) }}
                                {{? (!(prices.sales_price_unformatted == price_factor_conversao)) || (_.keys(it.childrens).length == 1)}}
                                    [ {{= BeevoCurrency.display(price_factor_conversao) }} / {{= it.extra_fields['unidade_medida_site'][un_product_id]['unidade_destino'] }} ]
                                {{?}}{{?}}
                            {{?}}
                        </div>
                        {{?}}
                    {{?}}

                {{?}}
            </div>
        </div>
    </div>
{{?}}
<script>
$(document).ready(function(){
  $('[data-toggle="tooltip"]').tooltip();
});
</script>

